const prompt = msg.prompt || (typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload));
let cmd = `agy -p ${JSON.stringify(prompt)} --dangerously-skip-permissions`;

if (msg.schema) {
    const schemaStr = typeof msg.schema === 'object' ? JSON.stringify(msg.schema) : msg.schema;
    cmd += ` --json-schema ${JSON.stringify(schemaStr)} --output-format json`;
}

msg.payload = cmd;
return msg;

const rc = typeof msg.rc === 'object' && msg.rc !== null ? Number(msg.rc.code) : Number(msg.rc);
if (rc === 0) {
    return null;
}

msg.aiError = true;
msg.payload = msg.payload || `agy 結束碼 ${rc}`;
return msg;

let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    parsed = { response: msg.payload };
}

let result = parsed.structured_output;
if (!result && parsed.response) {
    try {
        result = typeof parsed.response === 'string' ? JSON.parse(parsed.response) : parsed.response;
    } catch (e) {
        result = parsed.response;
    }
}

msg.payload = result || parsed;
return msg;

msg.aiError = true;
msg.payload = msg.payload || msg.rc || 'agy 執行失敗';
return msg;

// 設定最大允許並行數 MAX_CONCURRENCY = 1 (保護 CPU 不被多個 agy.exe 塞爆)
const MAX_CONCURRENCY = 1;
let activeCount = flow.get('active_ai_count') || 0;

if (activeCount >= MAX_CONCURRENCY) {
    node.warn(`🛑 [號誌鎖攔截] 當前已有 ${activeCount} 個 AI 任務執行中，任務 ${msg.payload} 進入降級處理！`);
    msg.status = 'THROTTLED';
    return [null, msg]; // 第 2 路: 降級處理
}

// 取得鎖，計數 +1，並為本次任務建立一次性 token
activeCount++;
const token = `sem_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
const activeTokens = flow.get('active_ai_tokens') || {};
activeTokens[token] = true;
flow.set('active_ai_count', activeCount);
flow.set('active_ai_tokens', activeTokens);
msg.semaphore_token = token;
node.status({ fill: 'green', shape: 'dot', text: `執行中 (${activeCount}/${MAX_CONCURRENCY})` });

msg.status = 'ACQUIRED';
return [msg, null]; // 第 1 路: 正常放行進入 AI

msg.prompt = `請簡要說明為什麼本機自動化需要控制 AI 並行數（任務：${msg.payload}）`;
msg.schema = {
  type: 'object',
  properties: {
    explanation: { type: 'string', description: '並行控制的白話說明' }
  },
  required: ['explanation']
};
return msg;

const token = msg.semaphore_token;
const activeTokens = flow.get('active_ai_tokens') || {};

// 同一個任務可能因 stdout 分段或多個輸出路徑重複抵達；只允許第一次 Release。
if (!token || !activeTokens[token]) {
    node.warn('⚠️ [Semaphore 防重複] 此訊息已釋放過名額，忽略重複 Release。');
    return null;
}

delete activeTokens[token];
let activeCount = flow.get('active_ai_count') || 1;
activeCount = Math.max(0, activeCount - 1);
flow.set('active_ai_count', activeCount);
flow.set('active_ai_tokens', activeTokens);
msg.active_ai_count = activeCount;

node.status({ fill: 'blue', shape: 'ring', text: `已釋放鎖 (剩餘 ${activeCount})` });
return msg;
